// Bundled Part Color Availability catalog: maps each top-level LDraw part ID to the sorted list
// of real-world LEGO colors (as standard LDraw LDConfig.ldr color IDs) that the part has
// actually been produced in. Generated by `scripts/build-part-colors.mjs` into
// `public/parts-catalog/part-colors.json` and loaded lazily alongside the Online Parts Catalog.

import { normalizeLibraryPartId } from './bricksLibrary';

export const PART_COLORS_FORMAT = 'brick-instruction-works-part-colors';
export const PART_COLORS_FILE = 'parts-catalog/part-colors.json';

export interface PartColorsCatalog {
  /** Sorted array of LDraw color IDs per normalized part ID. */
  byPart: ReadonlyMap<string, readonly number[]>;
  /** O(1) membership lookup set per normalized part ID. */
  byPartSet: ReadonlyMap<string, ReadonlySet<number>>;
  /** Total number of indexed parts available in each LDraw color ID. */
  partCountByColor: ReadonlyMap<number, number>;
}

/** Validates and parses a generated `part-colors.json` payload into a `PartColorsCatalog`. */
export function parsePartColorsPayload(payload: unknown): PartColorsCatalog {
  const byPart = new Map<string, readonly number[]>();
  const byPartSet = new Map<string, ReadonlySet<number>>();
  const partCountByColor = new Map<number, number>();

  const p = payload as { format?: unknown; parts?: unknown } | null;
  if (!p || p.format !== PART_COLORS_FORMAT || !p.parts || typeof p.parts !== 'object' || Array.isArray(p.parts)) {
    return { byPart, byPartSet, partCountByColor };
  }

  for (const [rawId, rawColors] of Object.entries(p.parts as Record<string, unknown>)) {
    if (!Array.isArray(rawColors) || rawColors.length === 0) continue;
    const id = normalizeLibraryPartId(rawId);
    if (!id) continue;

    const deduped = new Set<number>();
    for (const c of rawColors) {
      const colId = typeof c === 'number' ? c : Number(c);
      if (Number.isInteger(colId) && colId >= 0) {
        deduped.add(colId);
      }
    }
    if (deduped.size === 0) continue;

    const sorted = Array.from(deduped).sort((a, b) => a - b);
    const prev = byPart.get(id);
    if (prev) {
      for (const colId of prev) {
        const next = (partCountByColor.get(colId) ?? 1) - 1;
        if (next <= 0) partCountByColor.delete(colId);
        else partCountByColor.set(colId, next);
      }
    }
    byPart.set(id, sorted);
    byPartSet.set(id, deduped);
    for (const colId of sorted) {
      partCountByColor.set(colId, (partCountByColor.get(colId) ?? 0) + 1);
    }
  }

  return { byPart, byPartSet, partCountByColor };
}

/**
 * Lazily fetches `public/parts-catalog/part-colors.json` relative to `baseUrl`.
 * Returns `null` if unavailable (e.g. offline) so callers can retry on next open.
 */
export async function loadPartColorsCatalog(
  baseUrl = '',
  fetchImpl: typeof fetch = fetch,
): Promise<PartColorsCatalog | null> {
  try {
    const res = await fetchImpl(`${baseUrl}${PART_COLORS_FILE}`);
    if (!res.ok) return null;
    const parsed = parsePartColorsPayload(await res.json());
    return parsed.byPart.size > 0 ? parsed : null;
  } catch {
    return null;
  }
}
